<?php
namespace qqworld_collector\module\static_cache; use qqworld_collector\lib; class install extends lib { public function init() { add_action( 'qqworld-collector-static-cache-half-install', array($this, 'install') ); add_action( 'qqworld-collector-static-cache-half-uninstall', array($this, 'uninstall') ); add_action( 'qqworld-collector-register-deactivation-hook', array($this, 'uninstall') ); } public function install() { $path = WP_CONTENT_DIR . DIRECTORY_SEPARATOR . 'advanced-cache.php'; if ( !file_exists($path) ) { $codes = file_get_contents( QQWORLD_COLLECTOR_DIR . DIRECTORY_SEPARATOR . 'lib' . DIRECTORY_SEPARATOR . 'static-cache' . DIRECTORY_SEPARATOR . 'advanced-cache.php' ); $codes = str_replace('namespace qqworld_collector;', "namespace qqworld_collector;

define('WP_CACHE', true); // for Static Cache of QQWorld Collector Deluxe\r\ndefine('QQWORLD_STATIC_CACHE_EXPIRATION_TIME', ".($this->options->qc_static_cache_expiration*3600).");", $codes ); file_put_contents($path, $codes); } $path = WP_CONTENT_DIR . DIRECTORY_SEPARATOR . 'static-cache'; if ( !is_dir($path) ) mkdir($path); if ($this->options->cloud_storage_joinmode_enabled) { $path .= DIRECTORY_SEPARATOR . 'cs'; if ( !is_dir($path) ) mkdir($path); } } public function uninstall() { $path = ABSPATH . DIRECTORY_SEPARATOR . 'wp-config.php'; $wp_config = file_get_contents($path); if ( strstr($wp_config, 'WP_CACHE') !== false) { $wp_config = str_replace("\r\n\r\ndefine('WP_CACHE', true); // for Static Cache of QQWorld Collector Deluxe\r\n", '', $wp_config ); $wp_config = preg_replace('/define\(\'QQWORLD_STATIC_CACHE_EXPIRATION_TIME\', \d*\);\r\n/i', '', $wp_config); file_put_contents($path, $wp_config); } $path = WP_CONTENT_DIR . DIRECTORY_SEPARATOR . 'advanced-cache.php'; if ( file_exists($path) ) { unlink($path); } } } ?>